import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char[] s = sc.next().toCharArray();
        int[] a = new int[26];
        for (char c : s) {
            a[c - 'a']++;
        }
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < a[i]; j++) {
                System.out.print((char) ('a' + i));
            }
        }
        sc.close();
    }
}
